// Interval-scaled Dynkin corrections, no new Gaussian state or stock coupling.
#include "m2_protected_variance.cpp"
static void rich_time(double t,double k,double width,int kind,double&q,double&qd){
 if(kind<0){double a,ap;envelope(t,a,ap);double K=365./10+k*(.5+4/(3*std::sqrt(3.)));q=a/K;qd=ap/K;return;}
 const double pi=std::acos(-1.);const int ends[8]={27,55,57,85,118,148,153,183};double a,ap,A;
 if(t<ends[0]/365.){double T=ends[0]/365.,v=pi*t/(2*T);a=std::pow(std::cos(v),2);ap=-pi/(2*T)*std::sin(2*v);A=pi/(2*T);}
 else if(t>=ends[7]/365.){double T=10./365,v=pi*(t-ends[7]/365.)/(2*T);A=pi/(2*T);if(t>=ends[7]/365.+T){a=1;ap=0;}else{a=std::pow(std::sin(v),2);ap=A*std::sin(2*v);}}
 else {int j=0;while(t>=ends[j+1]/365.)++j;double gap=(ends[j+1]-ends[j])/365.,v=pi*(t-ends[j]/365.)/gap;A=pi/gap;a=std::pow(std::sin(v),2);ap=A*std::sin(2*v);}
 double C=kind==0?.5+4/(3*std::sqrt(3.)*width*width):std::sqrt(2/(pi*std::exp(1.)))*(1+1/(width*width));double B=k*C,K=B/2+std::sqrt(A*A+B*B/4);q=a/K;qd=ap/K;
}
static double rich_value(double q,double qd,double u,double k,double width,int kind){if(kind<0||kind==0){double z=std::tanh(u/width),d=1-z*z;return qd*z-q*k*(u/width+2*z/(width*width))*d;}double derivative=std::sqrt(2/std::acos(-1.))/width*std::exp(-u*u/(2*width*width));return qd*std::erf(u/(std::sqrt(2.)*width))-q*k*u*(1+1/(width*width))*derivative;}
extern "C" void rich_probe(int n,const double*t,const double*u,const double*k,const double*w,const int*kind,double*out){for(int i=0;i<n;++i){rich_time(t[i],k[i],w[i],kind[i],out[3*i],out[3*i+1]);out[3*i+2]=rich_value(out[3*i],out[3*i+1],u[i],k[i],w[i],kind[i]);}}
extern "C" void rich_stock(int nt,int pairs,int nd,int ne,int na,const int*tr,const double*dec,const double*root,const double*cross,const double*mean,const double*proj,const double*time,const double*dt,const int*seg,const int*coarse,const int*reference,const int*expiry,const double*norm,const double*p,const double*models,const double*alpha,const double*normalizers,double scale,uint64_t seed,double*out){
 Model m(models);std::vector<double> qa(nt*13),qd(nt*13);for(int t=0;t<nt;++t)for(int b=0;b<13;++b){double width=b?1+(b-1)%4/2:1;int kind=b?(b-1)%2:-1;double rate=normalizers[b?(b-1)/4:2];rich_time(time[t],rate,width,kind,qa[t*13+b],qd[t*13+b]);}std::vector<double>ds(nt),df(nt),ns(nt),nf(nt),cs(nt),cf(nt),rs(nt),rf(nt),qs(nt),qf(nt);for(int t=0;t<nt;++t){double h=dt[t];ds[t]=std::exp(-m.as*h);df[t]=std::exp(-m.af*h);ns[t]=std::sqrt(-std::expm1(-2*m.as*h));nf[t]=std::sqrt(-std::expm1(-2*m.af*h));rs[t]=std::sqrt(residual(m.as,h));rf[t]=std::sqrt(residual(m.af,h));cs[t]=std::sqrt(h-rs[t]*rs[t]);cf[t]=std::sqrt(h-rf[t]*rf[t]);qs[t]=-std::expm1(-2*m.as*time[t]);qf[t]=-std::expm1(-2*m.af*time[t]);}
 auto worker=[&](int begin,int end){for(int i=begin;i<end;++i){std::vector<double>s(nd,0),next(nd),z(nd+1),logs(4*na,0),hold(2*na,0);double zs=0,zf=0,refv[2]={},reflog[2]={};
 for(int t=0;t<nt;++t){uint64_t k=(uint64_t(t)*pairs+i)*(nd+3);for(int j=0;j<nd+1;++j)z[j]=gaussian(seed,k+j);double dw=std::sqrt(dt[t])*z[0],es=gaussian(seed,k+nd+1),ef=gaussian(seed,k+nd+2),bs=cs[t]*es+rs[t]*gaussian(seed^UINT64_C(0x2ad82d187dccb289),2*(uint64_t(t)*pairs+i)),bf=cf[t]*ef+rf[t]*gaussian(seed^UINT64_C(0x2ad82d187dccb289),2*(uint64_t(t)*pairs+i)+1),shock=.6*dw-.8*(std::sqrt(1-m.r)*bs+std::sqrt(m.r)*bf),pr[3]={};for(int j=0;j<nd;++j)for(int c=0;c<3;++c)pr[c]+=proj[c*nd+j]*s[j];
 for(int anti=0;anti<2;++anti){double sign=anti?-1:1,C=mean[3*t]+sign*pr[0],Y=mean[3*t+1]+sign*pr[1],F=mean[3*t+2]+sign*pr[2],old=G(p[0]*C+p[1]*std::pow(Y-p[2],2)+p[3]*std::pow(F-p[4],2),p)*std::exp(-norm[t]);double stress=(1-m.r)*std::exp(sign*m.bs*zs-.5*m.bs*m.bs*qs[t])+m.r*std::exp(sign*m.bf*zf-.5*m.bf*m.bf*qf[t]),H=(1-m.w)*old+m.w*stress,l=sp(-sign*pr[1]/scale);
 double hh[13];const int indices[3]={7,6,5};for(int j=0;j<13;++j){int mode=j?(j-1)/4:2;double width=j?1+(j-1)%4/2:1;int kind=j?(j-1)%2:-1;hh[j]=rich_value(qa[t*13+j],qd[t*13+j],sign*s[indices[mode]],normalizers[mode],width,kind);}for(int a=0;a<na;++a){const double*x=models+23*a;double v=m.f+(.2-m.f)*x[seg[t]]*H;for(int j=0;j<13;++j)v+=.5*m.f*alpha[13*a+j]*hh[j];if(coarse[t])hold[anti*na+a]=v;for(int grid=0;grid<2;++grid){double vv=grid?v:hold[anti*na+a];logs[(anti*na+a)*2+grid]+=-.5*vv*dt[t]+std::sqrt(vv)*sign*shock;}}
 if(reference[t])refv[anti]=m.f+(.2-m.f)*models[seg[t]]*((1-m.w)+m.w*stress);reflog[anti]+=-.5*refv[anti]*dt[t]+std::sqrt(refv[anti])*sign*shock;
 if(expiry[t]>=0){double*o=out+((uint64_t(anti*pairs+i)*ne+expiry[t])*(na+1)*2);for(int a=0;a<na;++a)for(int grid=0;grid<2;++grid)o[2*a+grid]=std::exp(logs[(anti*na+a)*2+grid]);o[2*na]=o[2*na+1]=std::exp(reflog[anti]);}
 }
 const double*r=root+uint64_t(tr[t])*nd*nd;for(int j=0;j<nd;++j){double v=cross[tr[t]*nd+j]*dw;for(int l=0;l<nd;++l)v+=r[j*nd+l]*z[l+1];next[j]=dec[tr[t]*nd+j]*s[j]+v;}s.swap(next);zs=ds[t]*zs+ns[t]*es;zf=df[t]*zf+nf[t]*ef;
 }}};std::vector<std::thread>threads;for(int j=0;j<4;++j)threads.emplace_back(worker,pairs*j/4,pairs*(j+1)/4);for(auto&t:threads)t.join();
}
